// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes: module, agent tool and text diffs"
// Changes: The changes module – what adopting a draft would do to its project. Takes the draft's four parts, the
//          project's current parts and optionally the draft's base parts. Pure, no DOM: the editor's Changes view
//          and the agent tool get_draft_changes share it, so both see the same thing.

import { analyzeGrammar } from './analysis'
import { EOF, SEP, ruleText, type LLAnalysis } from './grammar'
import { PARTS, partEquals, writeParts, type PartName, type Parts } from './parts'
import { precTable, type Rel } from './precedence'
import { defaultProjectData } from './project'
import { llSets, type LLSets } from './projectAnalysis'

/** One line of a line diff; `oldLine` is its number in the project's text, `newLine` in the draft's (1-based). */
export interface DiffLine {
  kind: 'same' | 'added' | 'removed'
  text: string
  oldLine: number | null
  newLine: number | null
}

/** Flags every part carries. */
export interface PartFlags {
  /** The draft's part differs from the project's current part (adopting it would change the project). */
  changed: boolean
  /**
   * The project's part differs from the draft's base part and the draft's part differs from it too; null when the
   * base was not given.
   */
  changedOnBothSides: boolean | null
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Spec #1 review fixes"
  // Changes: Whether the draft itself changed the part (draft ≠ base). A part changed only in the project has
  //          changed: true but changedInDraft: false – adopting it would revert the project's newer work.
  /** The draft's part differs from the draft's base part (the draft changed it); null when the base was not given. */
  changedInDraft: boolean | null
}

export interface DraftChanges {
  /** N, T and S of the definition, each diffed on its own. */
  definition: PartFlags & { nonterminals: DiffLine[]; terminals: DiffLine[]; start: DiffLine[] }
  grammarRules: PartFlags & { lines: DiffLine[] }
  reductionRules: PartFlags & { lines: DiffLine[] }
  precTable: PartFlags & PrecTableChanges
  /** The LL table derived from the definition and grammar rules on both sides. */
  llTable: LLTableChanges
  sets: SetChanges
}

export type NonterminalSets = Omit<LLSets['nonterminals'][number], 'nonterminal'>
export type PredictEntry = Omit<LLSets['predict'][number], 'rule'>

export interface SetChanges {
  /** Nonterminals whose Empty, First or Follow differ (old/new null = the nonterminal is missing on that side). */
  nonterminals: { nonterminal: string; old: NonterminalSets | null; new: NonterminalSets | null; changed: (keyof NonterminalSets)[] }[]
  /** Rules (by number) whose text or Predict set differ. */
  predict: { rule: number; old: PredictEntry | null; new: PredictEntry | null; changed: (keyof PredictEntry)[] }[]
}

/** A rule in an LL table cell: its number (as the tab shows it) and its text. */
export interface LLEntry {
  rule: number
  text: string
}

export interface LLCellChange {
  nonterminal: string
  terminal: string
  old: LLEntry[]
  new: LLEntry[]
}

export interface LLConflict {
  nonterminal: string
  terminal: string
  rules: LLEntry[]
}

export interface LLTableChanges {
  /** Cells whose rules differ (number or text), row by row; rows and columns of the draft's table, then the project's. */
  cells: LLCellChange[]
  /** Conflicts (cells with more than one rule) only the draft's table has, with the draft's rules. */
  newConflicts: LLConflict[]
  /** Conflicts only the project's table has, with the project's rules. */
  resolvedConflicts: LLConflict[]
}

/** A precedence cell (row = terminal on the stack, column = input terminal) whose relation differs; '' = empty. */
export interface PrecCellChange {
  stack: string
  input: string
  old: Rel
  new: Rel
}

export interface PrecTableChanges {
  /** Terminals only the draft's table has, in its order. */
  addedTerminals: string[]
  /** Terminals only the project's table has, in its order. */
  removedTerminals: string[]
  /** Changed cells, row by row over the draft's terminals, then the removed ones, then $ (each row in that order too). */
  cells: PrecCellChange[]
}

const linesOf = (text: string) => (text === '' ? [] : text.split('\n'))

/** Line diff of two texts (longest common subsequence of lines), in reading order; removed before added. */
export function lineDiff(oldText: string, newText: string): DiffLine[] {
  const a = linesOf(oldText)
  const b = linesOf(newText)
  // lcs[i][j] = length of the longest common subsequence of a[i..] and b[j..]
  const lcs = Array.from({ length: a.length + 1 }, () => new Array<number>(b.length + 1).fill(0))
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--) lcs[i][j] = a[i] === b[j] ? lcs[i + 1][j + 1] + 1 : Math.max(lcs[i + 1][j], lcs[i][j + 1])
  const out: DiffLine[] = []
  let i = 0
  let j = 0
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) {
      out.push({ kind: 'same', text: a[i], oldLine: i + 1, newLine: j + 1 })
      i++
      j++
    } else if (j >= b.length || (i < a.length && lcs[i + 1][j] >= lcs[i][j + 1])) {
      out.push({ kind: 'removed', text: a[i], oldLine: i + 1, newLine: null })
      i++
    } else {
      out.push({ kind: 'added', text: b[j], oldLine: null, newLine: j + 1 })
      j++
    }
  }
  return out
}

/** Relations of the precedence table as the grid shows it (terminals normalized, stale cells dropped). */
function precGrid(part: Parts['precTable']) {
  const t = precTable({ terminals: part.terminals, cells: part.cells, rules: '', input: '' })
  const terminals = t.columns.filter((c) => c !== EOF)
  const rel = new Map(t.rows.flatMap((row) => row.relations.map((r, i) => [row.terminal + SEP + t.columns[i], r] as const)))
  return { terminals, relation: (stack: string, input: string): Rel => rel.get(stack + SEP + input) ?? '' }
}

function precTableChanges(oldPart: Parts['precTable'], newPart: Parts['precTable']): PrecTableChanges {
  const before = precGrid(oldPart)
  const after = precGrid(newPart)
  const removedTerminals = before.terminals.filter((t) => !after.terminals.includes(t))
  const all = [...after.terminals, ...removedTerminals]
  const symbols = all.length ? [...all, EOF] : []
  const cells = symbols.flatMap((stack) =>
    symbols
      .map((input) => ({ stack, input, old: before.relation(stack, input), new: after.relation(stack, input) }))
      .filter((c) => c.old !== c.new),
  )
  return { addedTerminals: after.terminals.filter((t) => !before.terminals.includes(t)), removedTerminals, cells }
}

const grammarOf = (parts: Parts) => analyzeGrammar({ rules: parts.grammarRules, ...parts.definition }).ll

const union = (a: string[], b: string[]) => [...a, ...b.filter((x) => !a.includes(x))]

function llEntries(a: LLAnalysis | null, nonterminal: string, terminal: string): LLEntry[] {
  const rules = a?.table.get(nonterminal)?.get(terminal) ?? []
  return rules.map((rule) => ({ rule, text: ruleText(a!.rules[rule - 1]) }))
}

const sameEntries = (a: LLEntry[], b: LLEntry[]) => a.length === b.length && a.every((e, i) => e.rule === b[i].rule && e.text === b[i].text)

function llTableChanges(before: LLAnalysis | null, after: LLAnalysis | null): LLTableChanges {
  const rows = union(after?.N ?? [], before?.N ?? [])
  // $ stays the last column.
  const cols = union(after?.cols ?? [], before?.cols ?? []).sort((x, y) => Number(x === EOF) - Number(y === EOF))
  const cells: LLCellChange[] = []
  const newConflicts: LLConflict[] = []
  const resolvedConflicts: LLConflict[] = []
  for (const nonterminal of rows)
    for (const terminal of cols) {
      const old = llEntries(before, nonterminal, terminal)
      const now = llEntries(after, nonterminal, terminal)
      if (!sameEntries(old, now)) cells.push({ nonterminal, terminal, old, new: now })
      if (now.length > 1 && old.length <= 1) newConflicts.push({ nonterminal, terminal, rules: now })
      if (old.length > 1 && now.length <= 1) resolvedConflicts.push({ nonterminal, terminal, rules: old })
    }
  return { cells, newConflicts, resolvedConflicts }
}

const NO_SETS: NonterminalSets = { empty: false, first: [], follow: [] }
const NO_PREDICT: PredictEntry = { text: '', predict: [] }
const sameValue = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)

/** The fields of two entries that differ (a missing entry counts as empty). */
function changedFields<T extends object>(old: T | null, now: T | null, empty: T): (keyof T)[] {
  const a = old ?? empty
  const b = now ?? empty
  return (Object.keys(empty) as (keyof T)[]).filter((k) => !sameValue(a[k], b[k]))
}

function setChanges(before: LLAnalysis | null, after: LLAnalysis | null): SetChanges {
  const a = before ? llSets(before) : { nonterminals: [], predict: [] }
  const b = after ? llSets(after) : { nonterminals: [], predict: [] }
  const setsOf = (s: LLSets, n: string): NonterminalSets | null => {
    const e = s.nonterminals.find((x) => x.nonterminal === n)
    return e ? { empty: e.empty, first: e.first, follow: e.follow } : null
  }
  const predictOf = (s: LLSets, rule: number): PredictEntry | null => {
    const e = s.predict.find((x) => x.rule === rule)
    return e ? { text: e.text, predict: e.predict } : null
  }
  const nonterminals = union(
    b.nonterminals.map((x) => x.nonterminal),
    a.nonterminals.map((x) => x.nonterminal),
  )
    .map((nonterminal) => {
      const old = setsOf(a, nonterminal)
      const now = setsOf(b, nonterminal)
      return { nonterminal, old, new: now, changed: changedFields(old, now, NO_SETS) }
    })
    // A nonterminal on one side only is a change even when its sets are empty.
    .filter((x) => x.changed.length || !x.old !== !x.new)
  const rules = Math.max(a.predict.length, b.predict.length)
  const predict = Array.from({ length: rules }, (_, i) => {
    const old = predictOf(a, i + 1)
    const now = predictOf(b, i + 1)
    return { rule: i + 1, old, new: now, changed: changedFields(old, now, NO_PREDICT) }
  }).filter((x) => x.changed.length)
  return { nonterminals, predict }
}

const contentOf = (parts: Parts) => writeParts(defaultProjectData(), parts)

function partFlags(draft: Parts, project: Parts, base?: Parts): Record<PartName, PartFlags> {
  const d = contentOf(draft)
  const p = contentOf(project)
  const b = base && contentOf(base)
  const flags = (part: PartName): PartFlags => ({
    changed: !partEquals(part, d, p),
    changedOnBothSides: b ? !partEquals(part, p, b) && !partEquals(part, d, b) : null,
    changedInDraft: b ? !partEquals(part, d, b) : null,
  })
  return Object.fromEntries(PARTS.map((part) => [part, flags(part)])) as Record<PartName, PartFlags>
}

/**
 * What adopting the draft would do to the project: per part a "changed" flag (and, given the draft's base parts,
 * "changed on both sides"), line diffs of the text parts, precedence terminal and cell changes, and the effect on
 * the derived LL table and sets. The project is the old side, the draft the new one.
 */
export function draftChanges({ draft, project, base }: { draft: Parts; project: Parts; base?: Parts }): DraftChanges {
  const before = grammarOf(project)
  const after = grammarOf(draft)
  const flags = partFlags(draft, project, base)
  return {
    definition: {
      ...flags.definition,
      nonterminals: lineDiff(project.definition.nonterminals, draft.definition.nonterminals),
      terminals: lineDiff(project.definition.terminals, draft.definition.terminals),
      start: lineDiff(project.definition.start.trim(), draft.definition.start.trim()),
    },
    grammarRules: { ...flags.grammarRules, lines: lineDiff(project.grammarRules, draft.grammarRules) },
    reductionRules: { ...flags.reductionRules, lines: lineDiff(project.reductionRules, draft.reductionRules) },
    precTable: { ...flags.precTable, ...precTableChanges(project.precTable, draft.precTable) },
    llTable: llTableChanges(before, after),
    sets: setChanges(before, after),
  }
}
